let a = [1, 2, 3];
let b = a; // b ссылается на тот же массив!

b.push(4);
console.log(a); // [1, 2, 3, 4] — a тоже изменился!

// Для копирования:
let c = [...a]; // spread syntax — создаёт копию
c.push(5);
console.log(a); // [1, 2, 3, 4] (не изменился)
console.log(c); // [1, 2, 3, 4, 5]

let matrix = [
    [1, 2, 3],
    [4, 5, 6],
    [7, 8, 9]
];

console.log(matrix[1][2]); // 6 (вторая строка, третий столбец)
